export function uiPhrasesFor(language: Language): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [text, entry] of Object.entries(UI_PHRASES)) {
    out[text] = language === 'uz' ? entry.uz ?? text : entry[language];
  }
  return out;
}
